1	// Soporte exclusivo de las pruebas de spec-0. Complementa factory/regresion/helpers.ts (que este spec no puede editar).
2	// Selectores tomados del código de Moodle 5.3 en entorno/.moodle-src/. Las aserciones que deciden si un criterio se
3	// cumple están en los .spec.ts; acá solo hay esperas y comprobaciones de que cada paso auxiliar terminó bien.
4	import { expect, type Locator, type Page } from '@playwright/test';
5	import { CLAVE, bloquePregunta, prepararCaptura } from '../../../factory/regresion/helpers';
6	
7	export type TipoPregunta = 'multichoice' | 'truefalse' | 'essay';
8	export type Categoria = { id: string; contexto: string };
9	
10	type ConfigMoodle = { courseId: number; contextid: number; sesskey: string };
11	
12	const configMoodle = (page: Page): Promise<ConfigMoodle> =>
13	  page.evaluate(() => (window as unknown as { M: { cfg: ConfigMoodle } }).M.cfg);
14	
15	/** Nombre único que no contiene "Examen de regresión", para que abrirQuiz nunca tome este examen por QUIZ-REG. */
16	export const nombreUnico = (prefijo: string, proyecto: string) => `${prefijo} ${proyecto} ${Date.now()}`;
17	
18	/**
19	 * TinyMCE crea su iframe oculto y lo muestra al terminar de cargar sus módulos, lo que puede superar los 5 s por defecto
20	 * de expect con el servidor bajo carga. Es una espera de carga: la aserción sobre el editor no cambia.
21	 */
22	export const ESPERA_EDITOR = 30_000;
23	
24	/**
25	 * Inicio de sesión de las pruebas de profesor de spec-0. Igual que login() de helpers.ts, pero espera 'domcontentloaded'
26	 * en vez de 'load': la primera petición tras un arranque en frío de Moodle puede tardar más de 30 s en terminar de
27	 * cargar todos los recursos de la portada de login aunque el formulario ya esté usable. Cada paso siguiente
28	 * (fill, click, expect) sigue esperando por sí mismo a su elemento, y la aserción final es la misma.
29	 */
30	export async function iniciarSesion(page: Page, usuario: string) {
31	  await page.context().clearCookies();
32	  // net::ERR_ABORTED: una navegación anterior (o la recarga de una ventana emergente que se cerró) todavía estaba en curso
33	  // y el navegador la cancela al empezar esta. No es un fallo de Moodle: se reintenta una vez la misma navegación.
34	  for (let intento = 1; ; intento++) {
35	    try {
36	      await page.goto('/login/index.php', { waitUntil: 'domcontentloaded', timeout: 60_000 });
37	      break;
38	    } catch (error) {
39	      if (intento >= 2 || !String(error).includes('ERR_ABORTED')) throw error;
40	    }
41	  }
42	  // Con 'domcontentloaded' el formulario puede recargarse (navegación anterior que termina, scripts de la portada) entre el
43	  // fill y el clic, y entonces se envía vacío: Moodle responde "Unable to log in" aunque las credenciales sean correctas.
44	  // Se comprueba que los valores siguen en los campos justo antes de enviar y, si el envío fue rechazado, se repite
45	  // el formulario una vez. La aserción final (ya no hay #loginbtn) es la misma de login() de helpers.ts.
46	  for (let intento = 1; ; intento++) {
47	    await page.fill('#username', usuario);
48	    await page.fill('#password', CLAVE);
49	    await expect(page.locator('#username')).toHaveValue(usuario);
50	    await expect(page.locator('#password')).toHaveValue(CLAVE);
51	    await page.click('#loginbtn');
52	    try {
53	      await expect(page.locator('#loginbtn')).toHaveCount(0);
54	      return;
55	    } catch (error) {
56	      if (intento >= 2) throw error;
57	      await page.goto('/login/index.php', { waitUntil: 'domcontentloaded', timeout: 60_000 });
58	    }
59	  }
60	}
61	
62	/**
63	 * prepararCaptura() espera 'networkidle' con el límite por defecto de 30 s, que no alcanza cuando Moodle carga en frío
64	 * (TinyMCE, AMD, estilos). Se espera primero la misma condición con un límite mayor; luego prepararCaptura() la
65	 * encuentra ya cumplida. Devuelve las mismas máscaras; no cambia qué se compara.
66	 */
67	export async function prepararCapturaLenta(page: Page): Promise<Locator[]> {
68	  await page.waitForLoadState('networkidle', { timeout: 90_000 });
69	  return prepararCaptura(page);
70	}
71	
72	export async function idCursoQA101(page: Page): Promise<number> {
73	  await page.goto('/course/view.php?name=QA101');
74	  return (await configMoodle(page)).courseId;
75	}
76	
77	// ---------------------------------------------------------------------------------------------------------
78	// Examen
79	
80	export async function abrirFormularioExamen(page: Page, curso: number) {
81	  await page.goto(`/course/modedit.php?add=quiz&course=${curso}&section=0`);
82	  await expect(page.locator('#id_introeditor_ifr')).toBeVisible({ timeout: ESPERA_EDITOR });
83	}
84	
85	/**
86	 * Deja abierto el índice del curso (solo escritorio) para capturar siempre el mismo estado. Abierto o cerrado es una
87	 * preferencia guardada por usuario (drawer-open-index, boost/layout/drawers.php:34) que sobrevive entre corridas: no es
88	 * parte de la pantalla que se protege. En móvil no aplica: drawers.js:328 lo cierra al cargar sin mirar la preferencia.
89	 */
90	export async function abrirIndiceCurso(page: Page) {
91	  const abrir = page.getByRole('button', { name: 'Open course index' });
92	  if (await abrir.isVisible()) await abrir.click();
93	  await expect(page.getByRole('button', { name: 'Close course index' })).toBeVisible();
94	}
