96	/** Guarda con "Save and display" y devuelve el cmid del examen creado o editado. */
97	export async function guardarExamen(page: Page): Promise<number> {
98	  await page.getByRole('button', { name: 'Save and display' }).click();
99	  await expect(page).toHaveURL(/mod\/quiz\/view\.php\?id=\d+/);
100	  return Number(new URL(page.url()).searchParams.get('id'));
101	}
102	
103	export async function crearExamen(page: Page, curso: number, nombre: string): Promise<number> {
104	  await abrirFormularioExamen(page, curso);
105	  await page.locator('#id_name').fill(nombre);
106	  return guardarExamen(page);
107	}
