109	export async function eliminarExamen(page: Page, cmid: number) {
110	  const { sesskey } = await configMoodle(page);
111	  await page.goto(`/course/mod.php?delete=${cmid}&sesskey=${sesskey}`);
112	  await page.getByRole('button', { name: 'Yes', exact: true }).click();
113	  await expect(page).toHaveURL(/course\/(view|section)\.php/);
114	}
