116	// ---------------------------------------------------------------------------------------------------------
117	// Banco de preguntas
118	
119	/** cmid del banco compartido de QA101, leído de la lista de bancos del curso. */
120	export async function cmidBanco(page: Page, curso: number): Promise<number> {
121	  await page.goto(`/question/banks.php?courseid=${curso}`);
122	  const banco = page.locator('.shared-banks .questioncount[data-cmid]').first();
123	  await expect(banco).toBeAttached();
124	  return Number(await banco.getAttribute('data-cmid'));
125	}
