127	export const urlCategorias = (banco: number) => `/question/bank/managecategories/category.php?cmid=${banco}`;
128	const urlBanco = (banco: number, c: Categoria) => `/question/edit.php?cmid=${banco}&cat=${c.id},${c.contexto}`;
129	
130	export const filaCategoria = (page: Page, nombre: string): Locator =>
131	  page.locator(`li.qbank_managecategories-item[data-categoryname=${JSON.stringify(nombre)}]`);
132	
133	export const filaPregunta = (page: Page, nombre: string): Locator =>
134	  page.locator('#categoryquestions tbody tr', { hasText: nombre });
135	
136	/**
137	 * Crea una categoría propia en el banco. Es necesaria porque el banco sembrado no tiene categoría por defecto
138	 * (question_bank_helper.php:660 usa skipdefaultcategory): sin esto, las preguntas caerían en Álgebra.
139	 */
140	export async function crearCategoria(page: Page, banco: number, nombre: string): Promise<Categoria> {
141	  await page.goto(urlCategorias(banco));
142	  // El botón recibe su evento cuando el componente reactivo termina de cargar el estado.
143	  await page.waitForLoadState('networkidle', { timeout: 90_000 });
144	  await page.locator('#qbank_managecategories-addcategory [data-action="addeditcategory"]').click();
145	  const modal = page.locator('[data-region="modal"]').filter({ has: page.locator('input[name="name"]') });
146	  await modal.locator('input[name="name"]').fill(nombre);
147	  await modal.locator('[data-action="save"]').click();
148	  await expect(filaCategoria(page, nombre)).toHaveCount(1);
149	  await page.reload();
150	  const id = await filaCategoria(page, nombre).getAttribute('data-categoryid');
151	  const { contextid } = await configMoodle(page);
152	  return { id: String(id), contexto: String(contextid) };
153	}
154	
155	/** Escribe en un editor TinyMCE. `iframe` es el selector CSS de su iframe. */
156	export async function escribirEditor(page: Page, iframe: string, texto: string) {
157	  await expect(page.locator(iframe)).toBeVisible({ timeout: ESPERA_EDITOR });
158	  // El iframe ya es visible mientras TinyMCE sigue cargando: su "throbber" (aria-busy) tapa el editor e intercepta el
159	  // click. Se espera a que desaparezca antes de interactuar.
160	  await expect(page.locator('.tox-tinymce', { has: page.locator(iframe) }).locator('.tox-throbber')).toBeHidden({
161	    timeout: ESPERA_EDITOR,
162	  });
163	  const cuerpo = page.frameLocator(iframe).locator('body');
164	  await cuerpo.click();
165	  await cuerpo.fill(texto);
166	}
167	
168	/** Crea una pregunta desde el botón "Create a new question ..." del banco, dentro de la categoría indicada. */
169	export async function crearPregunta(page: Page, banco: number, categoria: Categoria, tipo: TipoPregunta, nombre: string) {
170	  await page.goto(urlBanco(banco, categoria));
171	  // edit.php:73 corta la página sin pintar el banco mientras la migración de mod_qbank siga en la cola de tareas ad hoc.
172	  await expect(
173	    page.getByRole('alert').filter({ hasText: 'transfer_question_categories' }),
174	    'Entorno: las tareas ad hoc de mod_qbank no terminaron; revisar el cron o ejecutarlas antes de esta prueba',
175	  ).toHaveCount(0);
176	  // Con teclado, no con click: en móvil, el punto de click de Playwright cae sobre elementos que están ANTES del botón
177	  // en el flujo (h2, filtros) o bajo la barra fija, aunque nada lo tape en el DOM. El teclado no depende de coordenadas
178	  // y recorre el mismo botón, el mismo diálogo y el mismo envío. El botón nace deshabilitado hasta que carga chooser.js
179	  // y el diálogo solo habilita "Add" al elegir un tipo: se espera cada estado porque press() no lo hace.
180	  const crear = page.getByRole('button', { name: /create a new question/i });
181	  await expect(crear).toBeEnabled();
182	  await crear.press('Enter');
183	  const tipoPregunta = page.locator(`#item_qtype_${tipo}`);
184	  await expect(tipoPregunta).toBeVisible();
185	  await tipoPregunta.press('Space');
186	  await expect(tipoPregunta).toBeChecked();
187	  const agregar = page.locator('#chooserform input.submitbutton');
188	  await expect(agregar).toBeEnabled();
189	  await agregar.press('Enter');
190	  await expect(page).toHaveURL(/question\/bank\/editquestion\/question\.php/);
191	
192	  await page.locator('#id_name').fill(nombre);
193	  await escribirEditor(page, '#id_questiontext_ifr', `Enunciado de ${nombre}`);
194	  if (tipo === 'multichoice') {
195	    await escribirEditor(page, '#id_answer_0_ifr', 'Correcta');
196	    await page.locator('#id_fraction_0').selectOption({ label: '100%' });
197	    await escribirEditor(page, '#id_answer_1_ifr', 'Incorrecta');
198	  } else if (tipo === 'truefalse') {
199	    await page.locator('#id_correctanswer').selectOption({ label: 'True' });
200	  }
201	  await page.locator('#id_submitbutton').click();
202	  await expect(page).toHaveURL(/question\/edit\.php/);
203	  await expect(filaPregunta(page, nombre)).toHaveCount(1);
204	}
205	
206	/** Add > from question bank > Switch bank > filtro de categoría > Add selected questions to the quiz. */
207	export async function agregarDesdeBanco(page: Page, examen: number, banco: number, categoria: string, preguntas: string[]) {
208	  await page.goto(`/mod/quiz/edit.php?cmid=${examen}`);
209	  await page.waitForLoadState('networkidle', { timeout: 90_000 });
210	  await page.locator('.last-add-menu a[data-bs-toggle="dropdown"]').click();
211	  await page.locator('.last-add-menu [data-action="questionbank"]').click();
212	
213	  // El modal abre en el banco privado del examen; las preguntas están en el banco del curso.
214	  await page.locator('#switch-question-bank').click();
215	  // bank_switcher.js oculta esta selección justo antes de registrar el clic de los enlaces.
216	  await expect(page.locator('.search-banks .form-autocomplete-selection.d-none')).toHaveCount(1);
217	  // Tras visitarlo, el banco también aparece en "recientes" con el mismo data-newmodid; "banks in course" siempre lo lista.
218	  await page.locator(`.course-shared-banks a[data-newmodid="${banco}"]`).click();
219	
220	  const filtro = page.locator('[data-filter-type="category"]');
221	  const entrada = filtro.locator('div.form-autocomplete-input input');
222	  await entrada.click();
223	  await entrada.fill(categoria);
224	  await filtro.locator('.form-autocomplete-suggestions li', { hasText: categoria }).click();
225	  await page.locator('[data-filteraction="apply"]').click();
226	
227	  for (const nombre of preguntas) {
228	    await filaPregunta(page, nombre).locator('input[type="checkbox"]').check();
229	  }
230	  await page.getByRole('button', { name: 'Add selected questions to the quiz' }).click();
231	  await expect(page).toHaveURL(/mod\/quiz\/edit\.php/);
232	}
233	
234	/** Borra todas las preguntas de la categoría con la confirmación del banco y comprueba que ya no se listan. */
235	export async function eliminarPreguntas(page: Page, banco: number, categoria: Categoria) {
236	  await page.goto(urlBanco(banco, categoria));
237	  const nombres = await page.locator('#categoryquestions tbody input[type="checkbox"]')
238	    .evaluateAll((casillas) => casillas.map((c) => (c as HTMLInputElement).name));
239	  const ids = nombres.filter((n) => /^q\d+$/.test(n));
240	  if (!ids.length) return;
241	  const { sesskey } = await configMoodle(page);
242	  const parametros = new URLSearchParams({
243	    deleteselected: ids[0].slice(1),
244	    deleteall: '1',
245	    sesskey,
246	    cmid: String(banco),
247	    returnurl: `/question/edit.php?cmid=${banco}`,
248	  });
249	  ids.forEach((q) => parametros.set(q, '1'));
250	  await page.goto(`/question/bank/deletequestion/delete.php?${parametros}`);
251	  await page.getByRole('button', { name: 'Delete', exact: true }).click();
252	  await expect(page).toHaveURL(/question\/edit\.php/);
253	  await page.goto(urlBanco(banco, categoria));
254	  await expect(page.locator('#categoryquestions tbody tr')).toHaveCount(0);
255	}
256	
257	export async function eliminarCategoria(page: Page, banco: number, categoria: Categoria) {
258	  const { sesskey } = await configMoodle(page);
259	  await page.goto(`${urlCategorias(banco)}&delete=${categoria.id}&sesskey=${sesskey}`);
260	  await expect(page).toHaveURL(/managecategories\/category\.php/);
261	}
262	
263	// ---------------------------------------------------------------------------------------------------------
264	// Intento y calificación
265	
266	/** Radio de una opción, con el mismo criterio de nombre accesible que elegir() en helpers.ts. */
267	export function opcion(page: Page, pregunta: number, texto: string): Locator {
268	  return bloquePregunta(page, pregunta).getByRole('radio', { name: new RegExp(`^([a-z0-9]+\\. )?${texto}$`, 'i') });
269	}
270	
271	/** Celda de estado de una pregunta en la tabla de summary.php. */
272	export const estadoEnResumen = (page: Page, pregunta: number): Locator =>
273	  page.locator(`table.quizsummaryofattempt tr.quizsummary${pregunta} td.c1`);
274	
275	/** Desde la última página del intento va a summary.php, sin enviar. */
276	export async function irAlResumen(page: Page) {
277	  await page.getByRole('button', { name: /finish attempt/i }).click();
278	  await expect(page).toHaveURL(/summary\.php/);
279	}
280	
281	export const idIntento = (page: Page) => Number(new URL(page.url()).searchParams.get('attempt'));
282	
283	/**
284	 * Celdas de la columna Time del historial de respuestas de comment.php. prepararCaptura no las cubre y la fábrica
285	 * no puede editar helpers.ts desde este spec. Se ubican por el texto del encabezado, no por posición.
286	 */
287	export async function celdasTiempoHistorial(page: Page): Promise<Locator> {
288	  const tabla = page.locator('div.responsehistoryheader table');
289	  const encabezados = await tabla.locator('thead th').allTextContents();
290	  const columna = encabezados.findIndex((t) => t.trim() === 'Time');
291	  expect(columna, `Encabezados del historial: ${encabezados.join(', ')}`).not.toEqual(-1);
292	  return tabla.locator(`tbody tr > :nth-child(${columna + 1})`);
293	}
